function renderStepper(){if(draft.created)return app(modal(success()));let labels=['Engagement','Client details','Scope','Review'];let steps=`<div class="steps">${labels.map((n,i)=>`<span class="${draft.step===i?'selected':''}"><i>${i+1}</i>${n}</span>`).join('')}</div>`;let content=draft.step===0?`<p class="section-title">How will you work with this client?</p><p class="section-copy">Choose the setup that matches the agreement.</p>${modeChoices()}`:draft.step===1?details():draft.step===2?draft.mode==='Monthly'?monthly():custom():review();return app(modal(steps+content,'stepper',footer(draft.step===3?'Create client →':'Continue →',draft.step===3?'create':'next')));}
